python3 << 'PYEOF'
import json

FLOW = "/work/output/artifacts/skill-flow-ixp-invoice-extraction-simulated/VendorInvoiceProcessing/VendorInvoiceProcessing/VendorInvoiceProcessing.flow"

with open(FLOW) as f:
    data = json.load(f)

# ── Replace edges that pointed to old postToSap with postInvoiceToSap1 ─────────
# Edges to remap:
#   e-decision-sap: checkConfidence:true → postInvoiceToSap1:input
#   e-hitl-sap:     hitlReview:completed → postInvoiceToSap1:input
#   e-sap-end:      postInvoiceToSap1:default → endAutoProcessed:input
#   e-sap-error:    postInvoiceToSap1:error → terminateError:input

# These edges still reference postToSap (old node id); update targetNodeId / sourceNodeId
for e in data["edges"]:
    if e.get("targetNodeId") == "postToSap":
        e["targetNodeId"] = "postInvoiceToSap1"
        print(f"Rewired {e['id']} target → postInvoiceToSap1")
    if e.get("sourceNodeId") == "postToSap":
        e["sourceNodeId"] = "postInvoiceToSap1"
        # http.v2 success port is "default" not "success"
        if e.get("sourcePort") == "success":
            e["sourcePort"] = "default"
        print(f"Rewired {e['id']} source → postInvoiceToSap1")

# If none of those edges exist yet (they weren't carried over), add them
existing_edge_ids = {e["id"] for e in data["edges"]}
needed_edges = [
    {"id": "e-decision-sap",  "sourceNodeId": "checkConfidence",      "sourcePort": "true",      "targetNodeId": "postInvoiceToSap1", "targetPort": "input"},
    {"id": "e-hitl-sap",      "sourceNodeId": "hitlReview",           "sourcePort": "completed",  "targetNodeId": "postInvoiceToSap1", "targetPort": "input"},
    {"id": "e-sap-end",       "sourceNodeId": "postInvoiceToSap1",    "sourcePort": "default",   "targetNodeId": "endAutoProcessed",  "targetPort": "input"},
    {"id": "e-sap-error",     "sourceNodeId": "postInvoiceToSap1",    "sourcePort": "error",     "targetNodeId": "terminateError",    "targetPort": "input"},
]
for ne in needed_edges:
    if ne["id"] not in existing_edge_ids:
        data["edges"].append(ne)
        print(f"Added edge {ne['id']}")

# Fix End node output mappings: remove sapDocumentId references if they reference
# postToSap (old node), and update them to reference postInvoiceToSap1
for n in data["nodes"]:
    if n["id"] in ("endAutoProcessed", "endReviewed", "terminateError"):
        outs = n.get("outputs", {})
        if "sapDocumentId" in outs:
            src = outs["sapDocumentId"].get("source", "")
            if "postToSap" in src:
                outs["sapDocumentId"]["source"] = src.replace("$vars.postToSap", "$vars.postInvoiceToSap1")
                print(f"Fixed sapDocumentId reference in {n['id']}")

# Ensure postInvoiceToSap1 variables are in variables.nodes
existing_var_ids = {v["id"] for v in data["variables"]["nodes"]}
new_vars = [
    {"id": "postInvoiceToSap1.output", "type": "object", "binding": {"nodeId": "postInvoiceToSap1", "outputId": "output"}},
    {"id": "postInvoiceToSap1.error",  "type": "object", "binding": {"nodeId": "postInvoiceToSap1", "outputId": "error"}},
]
for nv in new_vars:
    if nv["id"] not in existing_var_ids:
        data["variables"]["nodes"].append(nv)
        print(f"Added variable {nv['id']}")

# Update sapDocumentId output mapping on end nodes to reference new node
for n in data["nodes"]:
    if n["id"] in ("endAutoProcessed", "endReviewed"):
        n.setdefault("outputs", {})["sapDocumentId"] = {
            "source": "=js:$vars.postInvoiceToSap1.output && $vars.postInvoiceToSap1.output.id ? $vars.postInvoiceToSap1.output.id : null"
        }

with open(FLOW, "w") as f:
    json.dump(data, f, indent=2)

print("\nFinal edges:", [e["id"] for e in data["edges"]])
PYEOF

